<?php
require_once '/var/www/html/wp-load.php';
$ids=get_posts(['post_type'=>'product','post_status'=>['publish','draft','pending','private'],'posts_per_page'=>-1,'fields'=>'ids']);$n=0;$tech=0;
foreach($ids as $id){$p=wc_get_product($id);if(!$p)continue;$content=(string)get_post_field('post_content',$id);$title=$p->get_name();$sku=$p->get_sku();$terms=wp_get_post_terms($id,'product_cat',['fields'=>'names']);$cat=$terms[0]??'لوازم خانگی';$state=get_post_meta($id,'_bhc_catalog_quality_state',true);$source=get_post_meta($id,'_bhc_source_url',true);$specraw=get_post_meta($id,'_bhc_structured_specs',true);$spec=json_decode($specraw,true);$changed=false;
 if(mb_stripos($content,'درباره محصول')===false){$basis=$state==='reference_verified'&&$source?'این رکورد بر اساس منبع ثبت‌شده برای مدل محصول در کاتالوگ بهاران‌هوم نگهداری می‌شود.':'این رکورد فعلاً برای تکمیل صف کاتالوگ ثبت شده و منبع دقیق مدل آن هنوز در حال بررسی است؛ بنابراین مشخصات اعلام‌نشده به‌صورت حدسی وارد نشده‌اند.';$block=$state==='reference_verified'?' مشخصات مدل و ویژگی‌های قابل‌استناد در بخش اطلاعات فنی آمده است.':' محصول فعلاً ناموجود و غیرقابل انتشار عمومی است تا مدل کامل، نسخه منطقه‌ای و مشخصات آن با منبع قابل‌ردیابی تطبیق شود.';$content='<h2>درباره محصول</h2><p>'.esc_html($title).' در دسته «'.esc_html($cat).'» قرار دارد و با وضعیت ناموجود در کاتالوگ ثبت شده است. '.$basis.$block.'</p>'.$content; $changed=true;}
 if(mb_stripos($content,'اطلاعات فنی')===false){$rows='';if(is_array($spec)&&count($spec)>=1){foreach($spec as $k=>$v)$rows.='<tr><th>'.esc_html($k).'</th><td>'.esc_html($v).'</td></tr>';}$technical=$rows?'<h2>اطلاعات فنی</h2><table><tbody>'.$rows.'</tbody></table>':'<h2>اطلاعات فنی</h2><p>مشخصات فنی کامل این مدل پس از تطبیق منبع دقیق و کد کامل محصول تکمیل می‌شود؛ از درج مقدار حدسی خودداری شده است.</p>';$content.=$technical;$changed=true;$tech++;}
 if($changed){wp_update_post(['ID'=>$id,'post_content'=>$content]);$n++;}}
echo 'UPDATED|'.$n."\nTECHNICAL_SECTIONS|".$tech."\n";
